    rs=[r for r,c in cl]; cs=[c for r,c in cl]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    h=w=r1-r0+1=c1-c0+1
    if h!=w or len(cl)!=4: return None
    # diamond ring radius1 missing center: cells at Chebyshev distance1 on diagonal
    cells={(r,c) for r,c in cl}
    if (r0+c0) in cells and (r0+c1) in cells and (r1+c0) in cells and (r1+c1) in cells:
        return ('diag',r0,c0)   # incomplete ring, center at (r0+r1)/2... center=( (r0+r1)//2, (c0+c1)//2 )
    if (r0,c0) in cells and (r0,c1) in cells and (r1,c0) in cells and (r1,c1) in cells:
        return ('corners',r0,c0)
