            rr+=dr; cc+=dc; d+=1
        return None
    for r,c,v in cs:
        for dr,dc in ((0,-1),(0,1),(-1,0),(1,0)):
            s=obs(r,c,dr,dc)
            if s is None: continue
            # stop before obstacle at distance s, so paint cells strictly between source and obstacle
            j,jc=r,c
            while True:
                nj,njc=j+dr,jc+dc
                if nj==r+dr or jc==c+dc: break
                if I[nj][njc]!=0: break
                if (nj,njc)==(r,c): break
                reach.setdefault((nj,njc),[]).append(v); j,jc=nj,njc
    # conflicts: pick most frequent color; if tie use ... see mismatches first
    for (r,c),colors in reach.items():
        if len(colors)>1:
            col=max(set(colors),key=colors.count)
            O[r][c]=col
    return O
