from collections import Counter
import numpy as np
def comps(a,bg):
    H,W=len(a),len(a[0]); seen=[[False]*W for _ in range(H)]; cs=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and a[i][j]!=bg:
                col=a[i][j]; st=[(i,j)]; c=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; c.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<H and 0<=xx<W and a[yy][xx]==col and not seen[yy][xx]: st.append((yy,xx))
                cs.append((col,c))
    return cs
for n in ['1','2','3']:
    a=G['Demo pair '+n+' input']; o=G['Demo pair '+n+' output']
    bg=Counter(x for r_ in a for x in r_).most_common(1)[0][0]
    ca=comps(a,bg); co=comps(o,bg)
    print('pair',n,'bg',bg)
    print('  IN comps:',[(c,len(cs)) for c,cs in sorted(ca,key=lambda x:-len(x[1]))])
    print('  OUT comps:',[(c,len(cs)) for c,cs in sorted(co,key=lambda x:-len(x[1]))])

